What does this code print? What do the numbers mean, and would they still be the shortest distances if each edge had a different length?

from collections import deque
graph = {"A": ["B", "C"], "B": ["E"], "C": ["D"], "D": ["E"], "E": ["F"], "F": []}

def bfs(start):
    dist = {start: 0}
    q = deque([start])
    while q:
        node = q.popleft()
        for nb in graph[node]:
            if nb not in dist:
                dist[nb] = dist[node] + 1
                q.append(nb)
    return dist

print(bfs("A"))

`ok` is meant to check whether a tree, stored as nested `(key, left, right)` tuples, is a valid binary search tree. What does this print, and is the tree actually a valid BST?

def ok(node):
    if node is None:
        return True
    key, left, right = node
    if left and left[0] > key:
        return False
    if right and right[0] < key:
        return False
    return ok(left) and ok(right)

def inorder(node):
    return inorder(node[1]) + [node[0]] + inorder(node[2]) if node else []

tree = (50, (30, (20, None, None), (60, None, None)), (70, None, None))
print(ok(tree), inorder(tree))
